window.docContents[124].resolve({"/UD-III___-storage-and-commands/Assignment/#Core-C_________-natural-semantics--UD-III___-storage-and-commands--Assignment":{"contents":"The left side denotes a location and has the type of the right side. The order is the one C++17 fixes for assignment, the right operand before the left one. The location must be live.\n\n","context":"Core C++, natural semantics\u0009UD III, storage and commands","header":"3.2. Assignment","id":"/UD-III___-storage-and-commands/Assignment/#Core-C_________-natural-semantics--UD-III___-storage-and-commands--Assignment"}});